with target_issue as (
  select id from public.issues where issue_number = 1 limit 1
)
insert into public.articles (
  slug,
  title_ar,
  subtitle_ar,
  body_ar,
  cover_image,
  section,
  issue_id,
  status,
  author_name,
  published_at
)
values (
  'تحولات-القوة-الناعمة-تراجع-الأفضلية-الغربية-وصعود-دبلوماسية-الوساطة',
  'تحولات القوة الناعمة: تراجع الأفضلية الغربية وصعود دبلوماسية الوساطة',
  'تكشف خريطة النفوذ الدولي لعام 2026 عن تقارب متسارع بين القوى الكبرى وتآكل جزئي للأفضلية الغربية التقليدية، بالتوازي مع تحول الوساطة وبناء قنوات التواصل إلى مصدر نفوذ مستقل للدول الأصغر حجماً.',
  '<p>لم تعد خريطة النفوذ الدولي تعكس بصورة مباشرة حجم الترسانة العسكرية أو اتساع الناتج الاقتصادي للدول. فإلى جانب القوة الصلبة التي تفرض الحضور عبر الإكراه والموارد، تتشكل مساحة متنامية من المنافسة حول السمعة الدولية، والثقة المؤسسية، والقدرة على بناء الشراكات والتأثير في تصورات المجتمعات والحكومات. وتقدم تحولات عام 2026 صورة واضحة لإعادة توزيع تدريجية في هذه المساحة؛ إذ تتقلص الفجوة بين القوى الكبرى في صدارة التصنيفات العالمية، بينما تنجح دول أصغر حجماً في توسيع حضورها عبر الدبلوماسية والوساطة وفتح قنوات التواصل بين الأطراف المتعارضة.</p>
<h2>خريطة النفوذ الهادئ في عام 2026</h2>
<p>وفقاً لمؤشر القوة الناعمة العالمي الصادر عن مؤسسة Brand Finance في يناير 2026، احتفظت الولايات المتحدة بالمركز الأول عالمياً برصيد 74.9 نقطة من أصل 100، غير أن هذا الترتيب يخفي تراجعاً ملموساً بلغ 4.6 نقاط مقارنة بالعام السابق. وفي المقابل، واصلت الصين تقدمها في المركز الثاني برصيد 73.5 نقطة بزيادة قدرها 0.7 نقطة، لتتقلص الفجوة بين القوتين إلى 1.4 نقطة فقط. ولا تشير هذه الأرقام إلى انتقال مكتمل للقيادة الدولية من واشنطن إلى بكين، لكنها تكشف عن تغير ملموس في توازن الجاذبية والنفوذ المدرك بينهما، خصوصاً بعد أن تقدمت الصين على الولايات المتحدة للمرة الأولى في محور السمعة، وحققت ترتيباً أفضل في 19 سمة من أصل 35 سمة مرتبطة بصورة الدول.</p>
<div data-editorial-block="chart" data-block-payload=""></div>
<p>ولم يقتصر التراجع النسبي على واشنطن وحدها، حيث ربطت Brand Finance انخفاض رصيد الولايات المتحدة في محاور الثقة والحوكمة والعلاقات الدولية بتغيرات السياسات الأميركية وتداعيات خطاب «أميركا أولاً» لدى الجماهير الخارجية. وعلى الضفة الأوروبية، تراجعت المملكة المتحدة من المركز الثالث إلى الرابع برصيد 69.2 نقطة، كما سجلت ألمانيا وفرنسا انخفاضاً في درجاتهما. وفي خضم هذا التبدل، صعدت اليابان إلى المركز الثالث برصيد 70.6 نقطة رغم تراجع طفيف عن عامها السابق، مستندةً إلى صلابة عناصر الاستقرار الاقتصادي، والابتكار، وجودة المنتجات، والثقة المؤسسية، وهي مقومات منحت صورتها الدولية قدرة أكبر على الصمود أمام التقلبات السياسية.</p>
<div data-editorial-block="chart" data-block-payload=""></div>
<h2>من الانتشار الثقافي إلى فراغ المصداقية</h2>
<p>تؤكد هذه المعطيات أن تصدير الثقافة والمنتجات الاستهلاكية، على أهميته، لم يعد كافياً وحده لضمان نفوذ سياسي مستدام. فالولايات المتحدة لا تزال تمتلك امتداداً عالمياً عبر الجامعات والسينما والتكنولوجيا، وتوسّع الصين حضورها الاقتصادي والتقني، وتستند اليابان إلى سمعة الجودة والابتكار، كما بنت كوريا الجنوبية حضوراً ثقافياً لافتاً عبر الدراما والموسيقى والصناعات الإبداعية. غير أن الجاذبية باتت تُقاس بصورة الدولة ككل؛ إذ تنعكس التصورات المرتبطة بالحوكمة والاتساق في السياسات الخارجية مباشرةً على منسوب الثقة الدولية، وحين يتسع الفارق بين الخطاب والممارسة تتآكل قيمة الرصيد الثقافي مهما بلغ اتساعه.</p>
<blockquote><p>تفتح الثقافة الأبواب أمام الدول الكبرى، لكن المصداقية والقدرة على إبقاء قنوات الحوار مفتوحة هما ما يصنع الثقة السياسية في عالم متعدد الأقطاب.</p></blockquote>
<p>ومع اشتداد الاستقطاب بين القوى الكبرى وتراجع الثقة المتبادلة بين العواصم المتنافسة، تتقلص قنوات الاتصال المباشر في الأزمات الدولية، وهو ما يخلق فراغاً دبلوماسياً حقيقياً. ومن هذا الفراغ تحديداً، برزت مساحة مختلفة للنفوذ لا تشترط امتلاك أسواق ضخمة أو صناعات ثقافية عابرة للقارات، بل تعتمد على القدرة على جمع المتخاصمين وإدارة الخلافات بينهم عبر الوساطة.</p>
<h2>الوساطة بوصفها رصيداً استراتيجياً للدول الأصغر</h2>
<p>تمنح الوساطة الدول الصغيرة والمتوسطة وزناً دولياً يتجاوز حجمها العسكري والسكاني، لأنها تحولها إلى طرف يصعب الاستغناء عنه في الحسابات الدبلوماسية للأزمات. غير أن هذه الدول لا تمارس نمطاً واحداً من الحياد، بل توظف أصولاً دبلوماسية متباينة تتراوح بين سعة الوصول والهدوء التفاوضي والحياد المؤسسي والاستمرارية طويلة الأمد.</p>
<p>ففي منطقة الخليج، برز نموذجان متكاملان يوضحان تنوع هذا المسار. فقد طورت قطر منذ عام 2004 حضوراً دبلوماسياً نشطاً يستند إلى قدرتها على الاحتفاظ بقنوات اتصال مفتوحة مع جهات حكومية وغير حكومية متباينة، وهو ما تجلى في محطات بارزة شملت استضافة توقيع اتفاق الدوحة بين الولايات المتحدة وحركة طالبان في فبراير 2020 والمحادثات الأفغانية اللاحقة، فضلاً عن مشاركتها مع مصر والولايات المتحدة في جهود الوساطة التي أفضت إلى اتفاق وقف إطلاق النار وتبادل الأسرى في غزة خلال يناير 2025. وبموازاة هذا الحضور النشط، رسخت سلطنة عُمان مدرسة الدبلوماسية الهادئة القائمة على تجنب التصعيد وصيانة الثقة الإقليمية بعيداً عن الأضواء؛ إذ أدت مسقط دور قناة اتصال موثوقة بين واشنطن وطهران، واستضافت في 6 فبراير 2026 مشاورات منفصلة مع الوفدين الإيراني والأميركي لتهيئة الظروف نحو استئناف المفاوضات الدبلوماسية والفنية حول الملف النووي.</p>
<p>وعلى مسار موازٍ في أوروبا، تكشف التجربتان السويسرية والنرويجية عن القيمة التراكمية للمؤسسات والصبر الدبلوماسي. فقد حولت سويسرا حيادها التاريخي واحتضان جنيف للمنظمات الدولية إلى منظومة «المساعي الحميدة» التي تشمل استضافة المحادثات وتقديم الدعم الفني والتنظيمي، حيث رافقت أكثر من ثلاثين عملية سلام في أكثر من عشرين دولة خلال السنوات الأخيرة. أما النرويج، فقد راهنت على الاستثمار طويل الأمد منذ عام 1993 عبر المشاركة المستمرة والمتابعة الفنية في تسوية نزاعات ممتدة في الشرق الأوسط وكولومبيا والفلبين وغواتيمالا، بدءاً من تيسير محادثات أوسلو بين عامي 1992 و1993، وصولاً إلى شراكتها مع كوبا في دعم اتفاق السلام الكولومبي عام 2016، مما يبرهن أن الوساطة عملية تراكمية تُبنى بالصبر والخبرة لا بالمؤتمرات العابرة.</p>
<h2>حدود القوة الناعمة ومعادلة التعددية الجديدة</h2>
<p>ورغم اتساع مساحة التأثير التي تتيحها القوة الناعمة والوساطة، فإن كليهما يظل محكوماً بحدود واقعية واضحة. فالوسيط، مهما ارتفعت مصداقيته، لا يملك ضمانة للتوصل إلى اتفاق ولا يمتلك أدوات فرض التنفيذ إذا تغيرت حسابات المتفاوضين أو غابت الإرادة السياسية، كما أن الحضور الدبلوماسي الكثيف قد يضع الدولة الوسيطة تحت ضغوط متعارضة ويُعرّض سمعتها للتأثر عند تعثر المفاوضات. وبالمثل، لا تستطيع القوى الكبرى الحفاظ على نفوذها الناعم بمعزل عن استقرار مؤسساتها واتساق سياساتها الخارجية وقدرتها على الوفاء بالتزاماتها.</p>
<p>وهكذا تتشكل ملامح العالم متعدد الأقطاب لا بوصفه انتقالاً بسيطاً للزعامة من عاصمة إلى أخرى، بل بوصفه اتساعاً في دائرة الفاعلين القادرين على توجيه مساراته. وبين تنافس القوى الكبرى على صيانة صورتها ومصداقيتها، ونجاح الدول الأصغر في تحويل الثقة وقنوات التواصل إلى رصيد دولي، تتبلور خريطة جديدة للقوة لا تحددها القدرة على فرض الإرادة وحدها، بل أيضاً القدرة على جمع الأطراف المتعارضة وبناء مساحات ممكنة للتفاهم.</p>
<h3>المصادر والمراجع</h3>
<ul><li>Brand Finance — Global Soft Power Index 2026 (يناير 2026)</li><li>وزارة الخارجية القطرية ومكتب الاتصال الحكومي — جهود الوساطة والسياسة الخارجية</li><li>وزارة الخارجية العُمانية — بيان مشاورات مسقط مع الوفدين الإيراني والأميركي (6 فبراير 2026)</li><li>المجلس الفيدرالي السويسري — المساعي الحميدة لخدمة السلام (Good Offices)</li><li>وزارة الخارجية النرويجية — جهود النرويج في عمليات السلام منذ عام 1993</li></ul>',
  null,
  'geopolitics',
  (select id from target_issue),
  'published',
  'فريق التحرير',
  now()
)
on conflict (slug) do update set
  title_ar     = excluded.title_ar,
  subtitle_ar  = excluded.subtitle_ar,
  body_ar      = excluded.body_ar,
  cover_image  = excluded.cover_image,
  section      = excluded.section,
  issue_id     = excluded.issue_id,
  status       = excluded.status,
  author_name  = excluded.author_name,
  published_at = excluded.published_at;
